  "All",
  "Telegram Services",
  "Instagram Views",
  "Instagram Followers",
  "Instagram Followers India",
  "Instagram Likes",
  "Instagram Comments",
  "Instagram Channel",
  "YouTube Views",
  "YouTube Subscribers",
  "Facebook",
  "TikTok",
  "Website Traffic",
];

const currencySymbols = {
  INR: "₹",
  USD: "$",
  EUR: "€",
};

function formatNumber(number) {
  return new Intl.NumberFormat("en-IN").format(number);
}

